import{_ as a,H as t,f as s,i}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"06 | 虚拟DOM：为什么要关心React组件的渲染机制？","description":"","frontmatter":{},"headers":[{"level":2,"title":"虚拟 DOM","slug":"虚拟-dom","link":"#虚拟-dom","children":[{"level":3,"title":"真实 DOM 有什么问题？","slug":"真实-dom-有什么问题","link":"#真实-dom-有什么问题","children":[]}]},{"level":2,"title":"协调","slug":"协调","link":"#协调","children":[{"level":3,"title":"Diffing 算法","slug":"diffing-算法","link":"#diffing-算法","children":[]},{"level":3,"title":"触发协调的场景","slug":"触发协调的场景","link":"#触发协调的场景","children":[]},{"level":3,"title":"什么是 Fiber 协调引擎？","slug":"什么是-fiber-协调引擎","link":"#什么是-fiber-协调引擎","children":[]}]},{"level":2,"title":"螺旋学习曲线","slug":"螺旋学习曲线","link":"#螺旋学习曲线","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"现代ReactWeb开发实战/06｜虚拟DOM：为什么要关心React组件的渲染机制？.md","filePath":"现代ReactWeb开发实战/06｜虚拟DOM：为什么要关心React组件的渲染机制？.md","lastUpdated":1795558962000}'),n={name:"现代ReactWeb开发实战/06｜虚拟DOM：为什么要关心React组件的渲染机制？.md"};function p(l,e,c,o,h,r){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="_06-虚拟dom-为什么要关心react组件的渲染机制" tabindex="-1">06 | 虚拟DOM：为什么要关心React组件的渲染机制？ <a class="header-anchor" href="#_06-虚拟dom-为什么要关心react组件的渲染机制" aria-label="Permalink to &quot;06 | 虚拟DOM：为什么要关心React组件的渲染机制？&quot;">​</a></h1><p>你好，我是宋一玮。欢迎回到 React 组件的学习。</p><p>上节课我们从前端组件化这个概念开始，学习了 React 组件的层次结构，并用第三节课的React 项目演练了组件拆分，引出了 React 拆分组件的基本原则，也顺带着提出 React 组件树的本质是元素树。</p><p>上节课的内容是比较多的。如果你有做过上节课的思考题，我仍然有些好奇，课上学到的内容是不是足够你完成题目。如果你顺利交卷那你真是很棒！当然，做题时遇到些难题也没关系，在这节课我会延续上节课的思路，继续讲 React 组件，重点会落在 React 组件的渲染机制上。</p><p>这节课会涉及一些 React 的底层原理，可以为你解答如下问题：</p><ul><li><p>为什么我需要关心 React 组件的渲染机制？</p></li><li><p>为什么数据变了，但组件没重新渲染？</p></li><li><p>为什么数据没变，但组件也重新渲染了？</p></li></ul><p>后两个问题本身都可以作为第一个问题的答案。至于后两个问题，掌握 React 组件重新渲染的时机，避免无效的重新渲染都需要学习 React 组件的渲染机制。</p><p>我们现在开始这节课的内容。</p><h2 id="虚拟-dom" tabindex="-1">虚拟 DOM <a class="header-anchor" href="#虚拟-dom" aria-label="Permalink to &quot;虚拟 DOM&quot;">​</a></h2><p>虚拟 DOM（Virtual DOM）是前端领域近几年比较出圈的一个概念，是相对于 HTML DOM（Document Object Model，文档对象模型）更轻量的 JS 模型。在 React、Vue.js、Elm 这样的声明式前端框架中，都包含了虚拟 DOM。</p><p>面向前端开发者，React 提供了包括 JSX 语法在内的声明组件 API，在运行时，开发者声明的组件会渲染成虚拟 DOM，虚拟 DOM 再由 React 框架渲染成真实的 DOM；虚拟 DOM 的变动，最终会自动体现在真实 DOM 上；真实 DOM 上的交互，也会由 React 框架抽象成虚拟DOM 上的副作用（Side-effect），与开发者编写的交互逻辑关联起来。</p><p>理想状态下，开发者在开发 React 应用时，可以完全不去接触真实 DOM（但现实世界中这种情况很少见），一定程度上隐藏了 Web 原生技术的细节，有助于提高开发效率。</p><p>如下图所示，左半边展示了 React 面向开发者的 API，右半边则是 React 内部实现对 DOMAPI 的封装，渲染面向用户的页面：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/1.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>虽然很不严谨，我们姑且可以对比一下 oh-my-kanban 项目目前为止的代码量和它在浏览器</span></span></code></pre></div><p>运行时生成的 HTML 的字符数。</p><p>如下图，左手边是 2.8k JSX + 1.8k CSS = 4.6k，右手边是从浏览器开发者工具的检查器页签里拷贝出来的实际 HTML 共 8.7k。要知道，检查器显示的 HTML 中并不包含事件处理函数等JS 内容，所以实际上 React 帮你节省了更多代码量。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/2.png" alt=""></a></p><p>比起代码量的减少，虚拟 DOM 更重要的功能之一，是作为 React 面向开发者的 API 与React 内部实现对接的桥梁。React API 整体都是声明式的，而 DOM API 是命令式的。我们知道，No Magic（没有魔法），开发者用 API 声明的 React 组件，最终成为页面上的动态DOM 元素，必然在 React 框架内部有着一系列命令式的实现，负责最终调用浏览器 DOMAPI。</p><p>如果没有虚拟 DOM 这个中间模型，那么 React API 就需要直接对接 DOM API，耦合程度提高，React 概念和 API 设计也会受制于浏览器，React Native 这样对接多端的愿景也无从实现了，React 也许就很难称作是 React 了。</p><h3 id="真实-dom-有什么问题" tabindex="-1">真实 DOM 有什么问题？ <a class="header-anchor" href="#真实-dom-有什么问题" aria-label="Permalink to &quot;真实 DOM 有什么问题？&quot;">​</a></h3><p>上面是从抽象设计和编程范式角度来介绍虚拟 DOM 的，有没有什么更有制约性的因素，导致不上虚拟 DOM 不行的？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有的。前面的课程里我们介绍过 React 的设计哲学 UI=f(state) ，理论上来说，对于给定</span></span>
<span class="line"><span>的 f() 和状态数据，一定可以重现一模一样的 UI；这也意味着，只要状态数据有变化，f()</span></span></code></pre></div><p>就需要重新执行，整个 UI 需要重新渲染。</p><p>是的，整个。如果这个渲染过程非常快，消耗资源也很低，那么我们让它每秒钟完整跑 120次都是 ok 的，120FPS 是什么样的体验呢？李安的电影《比利·林恩的中场战事》就是。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>但是正如 120FPS 的电影拍摄贵，放映更贵，现实世界的 f() 成本也是可观的。对于浏览器</span></span></code></pre></div><p>网页中的应用，我们降低一档标准，60FPS，意味着 1000ms ÷ 60 ≈ 16ms 之内至少需要执行</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>完一次 f() ，否则会掉帧，显示和交互都会卡顿。</span></span></code></pre></div><p>操作真实 DOM 是比较耗费资源的，无脑地大量调用 DOM API 绘制页面，页面很容易就卡了，如果碰巧你的电脑配置不是很理想，浏览器的高 CPU 和内存占用也会强迫你的电脑风扇发出哀嚎。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这时就需要 React 提供一系列算法和过程，过滤掉没有必要的 DOM API 调用，最终把f() 的</span></span></code></pre></div><p>成本降下来。虚拟 DOM 就是这些算法过程的中间模型，它远比 DOM API 轻量，跟最终的DOM API 分摊成本后，可以保证 React 组件的渲染效率。</p><p>在这里我就不列举 benchmark 数据了，你如果感兴趣的话，可以去上手玩一下 <a href="https://dom-benchmark.vercel.app/%EF%BC%8C%E6%BA%90%E7%A0%81%E5%9C%A8" target="_blank" rel="noreferrer">https://dom-benchmark.vercel.app/，源码在</a> <a href="https://github.com/Swizec/dom-benchmark%EF%BC%8C%E8%99%BD%E7%84%B6%E9%87%8C%E9%9D%A2React" target="_blank" rel="noreferrer">https://github.com/Swizec/dom-benchmark，虽然里面React</a> 测试程序使用的版本是比较早的 v16.2，但它的性能已经明显优于直接调用原生 DOMAPI 的测试程序了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/3.png" alt=""></a></p><p>其实在前端开源社区里，也有反对虚拟 DOM 的声音，比如新兴框架 Svelte 的作者里奇·哈里斯就曾发文《虚拟 DOM 纯粹就是额外开销》，认为虚拟 DOM 的 Diffing 算法是有代价的，也会误导开发者做一些无用功。</p><p>虽然与本课程立场不同，但我很认同他的最后一段文字：</p><ul><li>虚拟 DOM 的价值在于，当你构建应用时，无需考虑状态的变化如何体现在 UI 上，且一般情况下不用担心性能问题。这减少了代码 Bug，比起乏味的编码，你可以把更多时间投入到创造性的工作上。</li></ul><h2 id="协调" tabindex="-1">协调 <a class="header-anchor" href="#协调" aria-label="Permalink to &quot;协调&quot;">​</a></h2><p>上节课最后讲到 React 组件会渲染出一棵元素树。因为开发者使用的是 React 的声明式API，在此基础上，每次有 props、state 等数据变动时，组件会渲染出新的元素树，React 框架会与之前的树做 Diffing 对比，将元素的变动最终体现在浏览器页面的 DOM 中。这一过程就称为协调（Reconciliation）。</p><h3 id="diffing-算法" tabindex="-1">Diffing 算法 <a class="header-anchor" href="#diffing-算法" aria-label="Permalink to &quot;Diffing 算法&quot;">​</a></h3><p>Svelte 作者的文章是 2018 年底发布的，React 框架的核心开发团队不可能没看到吧。不过就算没有这篇文章，React 框架后续的版本中也在不断优化 Diffing 算法。近四年算法细节变了不少，但基本逻辑还是能归纳出以下几点：</p><ol><li><p>从根元素开始，React 将递归对比两棵树的根元素和子元素；</p></li><li><p>对比不同类型的元素，如对比 HTML 元素和 React 组件元素，React 会直接清理旧的元素和它的子树，然后建立新的树；</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>对比同为 HTML 元素，但 Tag 不同的元素，如从 &lt;​a&gt; 变成 &lt;​div&gt; ，React 会直接清理旧</span></span></code></pre></div><ul><li>的元素和子树，然后建立新的树；</li></ul><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">对比同为 React 组件元素，但组件类或组件函数不同的元素，如从 KanbanNewCard 变成</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KanbanCard ，React 会卸载旧的元素和子树，然后挂载新的元素树；</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">对比 Tag 相同的 HTML 元素，如  &lt;​input type=&quot;text&quot; value=&quot;old&quot; /&gt; 和</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​input type=&quot;text&quot; value=&quot;new&quot; /&gt; ，React 将会保留该元素，并记录有改变的</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">属性，在这个例子里就是 value 的值从 &quot;old&quot; 变成了 &quot;new&quot; ；</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">对比组件类或组件函数相同的组件元素，如 &lt;​KanbanCard title=&quot;老卡片&quot; /&gt; 和</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​KanbanCard title=&quot;新卡片&quot; /&gt; ，React 会保留组件实例，更新 props，并触发组件</span></span></code></pre></div><ul><li>的生命周期方法或者 Hooks。</li></ul><p>需要强调的是，在对比两棵树对应节点的子元素时，如果子元素形成一个列表，那么 React 会按顺序尝试匹配新旧两个列表的元素。</p><p>如果对比结果是在列表末尾新增或者减少元素那还好，但如果是在列表头部或者中间插入或者删除元素，React 就不知道该保留哪个元素了，干脆把整个列表都推翻了重建，这样会带来性能损耗。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为了应对这种情况，React 引入了 key 这个特殊属性，当有子元素列表中的元素有这个属性</span></span></code></pre></div><p>时，React 会利用这个 key 属性值来匹配新旧列表中的元素，以减少插入元素时的性能损耗。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这样的用途就要求在任何一个子元素列表中，key 对于每个元素应该是唯一的且稳定的。比</span></span>
<span class="line"><span>如你的数据来自于数据库，包含了自增 ID，那么你就可以用这个 ID 当作 key 的值。</span></span>
<span class="line"><span>你一拍大腿，终于知道 oh-my-kanban 在浏览器控制台里的 warning 是哪里来的了。</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/4.png" alt=""></a></p><p>一直放在这里不修倒不是不可以，毕竟已经忽视它 3 节课了，但你既然知道这个 warning 的代</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>价了，就不妨把它修掉。手头实在是没有 ID，就把 title 赋给 key 属性吧。</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/5.png" alt=""></a></p><p>刷新页面，浏览器控制台终于清静了！这时查看 React 开发者工具的组件页签，呈现的组件树是这样的：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/6.png" alt=""></a></p><p>Diffing 的结果最终会被转换成 DOM API 调用，我们只修改需要修改的 DOM 即可。</p><h3 id="触发协调的场景" tabindex="-1">触发协调的场景 <a class="header-anchor" href="#触发协调的场景" aria-label="Permalink to &quot;触发协调的场景&quot;">​</a></h3><p>了解了什么是协调，以及协调对比算法的基本逻辑，我们再回到 React 应用开发者的视角，看一下开发者做什么事情时会触发协调。</p><p>首先，开发者在使用 React API 时，不应该随时想着协调的细节，否则会加重开发者的负担；但协调又是页面最终变化的必经之路，这在前面已经强调过。那么如果你是 React 框架的设计者，你会选择在什么情况下触发协调？一般而言你会有两个方向的选择，拉（Pull）或者推（Push）。</p><p>轮询（Polling）就是一种“拉”的方案，我们假设一个极端的设计，让 React 间隔每 16ms 触发一次协调，这从功能上是一定可以实现需求的，只要 React 元素树有风吹草动，这一次的协调就会算出 Diff，更新页面。但很容易就能看出这种方式的问题，也许元素树很长时间都没有变过，这会导致做了太多次没必要的协调，增加了资源的开销。</p><p>那么我们选择“推”的方案。我们要有方式告诉 React，说我们需要触发协调，而且这个方式应该停留在 React API 层面，否则会把协调这一内部过程的复杂性暴露给开发者。结合 React 的</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设计哲学，UI=f(state) （这个 state 泛指组件数据，不是 React 接口里哪个 state），我们</span></span></code></pre></div><p>认为只有数据变化时，才需要触发协调。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这就好办了，在 React API 里有哪些是操作组件数据的？是的， props 和 state ，除此之</span></span>
<span class="line"><span>外再加一个 context。其中props 从组件外面传进来，state 则是活跃在组件内部，至于</span></span>
<span class="line"><span>context ，在组件外面的 Context.Provider 提供数据，组件内部则可以消费 context 数据。</span></span></code></pre></div><p>只要这三种数据之一发生了变化，React 就会对当前组件触发协调过程，最终按照 Diffing 结果更改页面。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>关于 props、state 和 context 的细节，我依然计划留到后面的课程讲解。在这里先划出</span></span>
<span class="line"><span>一个重点，props 和 state 都是不可变的（Immutable）。</span></span>
<span class="line"><span>其中 state 的不可变性你可能还有印象，第三节课中你写 oh-my-kanban 的过程中，使用</span></span>
<span class="line"><span>了 setTodoList() 这样的 setState 方法来更新 state 数据，页面才能正确做出反应。</span></span>
<span class="line"><span>至于 props，我们尝试一下用这种方式改写 KanbanCard （临时改动），在组件内部给 props</span></span></code></pre></div><p>多加一个属性，看看会发生什么：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">const KanbanCard = (props) =&gt; {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> props.justWantToSetNewProp = &#39;尝试修改props对象&#39;;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> return (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   &lt;​li className=&quot;kanban-card&quot;&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     &lt;​div className=&quot;card-title&quot;&gt;{props.title}&lt;​/div&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     &lt;​div className=&quot;card-status&quot;&gt;{props.justWantToSetNewProp} {props.status}&lt;​/d</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   &lt;​/li&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> );</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>页面白了，React 并不允许这样操作 props：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/7.png" alt=""></a></p><p>简单来说，一个组件的 props 应该由父组件传进来，props 数据的变动也应该由父组件负责。</p><h3 id="什么是-fiber-协调引擎" tabindex="-1">什么是 Fiber 协调引擎？ <a class="header-anchor" href="#什么是-fiber-协调引擎" aria-label="Permalink to &quot;什么是 Fiber 协调引擎？&quot;">​</a></h3><p>虽然前面一直在提虚拟 DOM，但翻遍 React 的 API 文档和源代码，也找不到任何一个类、函</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数或者变量叫 VirtualDOM ，它更多还是一个抽象概念。React 中最接近这个概念的实现，</span></span></code></pre></div><p>你猜是什么？你说是 React 元素。嗯，是个好答案。不过要深究 React 协调的技术细节，那么这个答案也对也不对。</p><p>在 React 的早期版本，协调是一个同步过程，这意味着当虚拟 DOM 足够复杂，或者元素渲染时产生的各种计算足够重，协调过程本身就可能超过 16ms，严重的会导致页面卡顿。</p><p>而从 React v16 开始，协调从之前的同步改成了异步过程，这主要得益于新的 Fiber 协调引</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>擎。从此在 React 中更贴近虚拟 DOM 的，是在 Fiber 协调引擎中的核心模型 FiberNode。</span></span></code></pre></div><p>FiberNode 依靠对元素到子元素的双向链表、子元素到子元素的单向链表实现了一棵树，这棵树可以随时暂停并恢复渲染，触发组件生命周期等副作用（Side-effect），并将中间结果分散保存在每一个节点上，不会 block 浏览器中的其他工作。</p><p>Fiber 引擎细节比较多，这里暂不展开。你若感兴趣的话请在留言区告诉我，后期也许会有加餐。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/8.png" alt=""></a></p><h2 id="螺旋学习曲线" tabindex="-1">螺旋学习曲线 <a class="header-anchor" href="#螺旋学习曲线" aria-label="Permalink to &quot;螺旋学习曲线&quot;">​</a></h2><p>在本节课收尾之前，我想聊些题外话。认真学习的你一定还记得，前面的课程中我挖了不少坑，比如 props、state、单向数据流、组件生命周期、事件处理、高阶组件、编译工具等等，那到底什么时候才填坑呢？不急，这节课依然会涉及部分概念，但还没到填坑的时候。</p><p>对于学习一门新技术，大家普遍认为过程符合下图这样的学习曲线：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/9.png" alt=""></a></p><p>然而我从自己和身边同事朋友的经历中，观察到实际上的学习曲线并不是二维的，而是三维的螺旋曲线，如下图所示（用 PowerPoint 画 3D 简直自虐，谁能教我 Blender）：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%8E%B0%E4%BB%A3ReactWeb%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/06/10.png" alt=""></a></p><p>在螺旋曲线中学习过程会经历：学习技术表层 → 学习技术底层 → 回过头来理解表层 → 继续学习更多表层 → 底层 → …如此往复… → 掌握技术。当然，并不是所有人都是这样学习的，但我希望在这门课程中用这一方法能帮到你。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>在这节课里，我们学习了 React 中的虚拟 DOM 远是真实 DOM 的抽象，且远比后者更轻量，是 React 面向开发者的 API 与内部实现对接的桥梁。也介绍了 React 组件的 props、state 或者 context 改变时，React 会触发协调过程对比新旧两棵元素树，计算出有哪些真实 DOM 需要变更。</p><p>这些就是 React 组件的渲染机制。理解了渲染机制，你就更清楚该如何写出对的组件、快的组件。</p><p>下节课我们会稍微轻松一下，转过头来聊聊决定 Web 应用样式的 CSS，看看在 React 应用中如何写 CSS。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li>这节课中间讲 Diffing 对比算法时，提到 React 将会保留相同 Tag 的 HTML 元素，并记录有改变的属性。请你思考这里该如何判断属性是否被修改了？对于 JS 各种数据类型是如何判断相等的？这些判断相等的逻辑在 React 内部很多地方都有应用。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>既然每次协调都会调用组件的 render() 方法，而render() 方法都是开发者实现的，那</span></span>
<span class="line"><span>万一没写好，导致render() 每次执行都有很大开销，会对 React 渲染产生什么后果？另</span></span></code></pre></div><ul><li>外在 JS 里，写什么样的代码会产生很大开销呢？</li></ul><p>欢迎把你的思考和想法分享在留言区，我们下节课再见！</p>`,98)])])}const E=a(n,[["render",p]]);export{d as __pageData,E as default};
